name: Comment artifacts on PR

on:
  workflow_run:
    workflows: ["test-build.yml"]
    types:
      - completed

permissions:
  pull-requests: write
  contents: read

jobs:
  comment-artifacts:
    if: ${{ github.event.workflow_run.conclusion == 'success' && github.event.workflow_run.event == 'pull_request' }}
    runs-on: ubuntu-latest
    steps:
      - name: Download ISO artifact
        id: download
        uses: dawidd6/action-download-artifact@v11
        with:
          github_token: ${{ secrets.GITHUB_TOKEN }}
          run_id: ${{ github.event.workflow_run.id }}
          name: iso
          path: artifacts

      - name: Find PR number
        id: get_pr
        uses: actions/github-script@v6
        with:
          script: |
            const sha = '${{ github.event.workflow_run.head_sha }}';
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const { data: prs } = await github.request('GET /repos/{owner}/{repo}/commits/{ref}/pulls', {
              owner,
              repo,
              ref: sha
            });
            if (prs.length === 0) {
              core.setFailed('No PR found for commit');
              return;
            }
            core.setOutput('pr_number', prs[0].number);

      - name: Build comment message
        id: comment_message
        uses: actions/github-script@v6
        with:
          script: |
            const artifacts = JSON.parse('${{ steps.download.outputs.artifacts }}');
            const artifact = artifacts.find(a => a.name === 'iso');
            if (!artifact) {
              core.setFailed('ISO artifact not found');
              return;
            }
            const runId = '${{ github.event.workflow_run.id }}';
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const link = `https://github.com/${owner}/${repo}/actions/runs/${runId}/artifacts/${artifact.id}`;
            const message = `ISO artifact available: ${link}`;
            core.setOutput('message', message);

      - name: Comment on PR
        uses: thollander/actions-comment-pull-request@e4a76dd2b0a3c2027c3fd84147a67c22ee4c90fa
        with:
          message: ${{ steps.comment_message.outputs.message }}
          pr-number: ${{ steps.get_pr.outputs.pr_number }}
          github-token: ${{ secrets.GH_TOKEN }}
          comment-tag: iso-artifact
          mode: replace
          create-if-not-exists: true
